import{_ as t}from"./chunks/site-models.D4MLFUg0.js";import{_ as a,o as d,c as o,a3 as s}from"./chunks/framework.BTt0kA_k.js";const b=JSON.parse('{"title":"站点与模型","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/sites.md","filePath":"user/use/sites.md"}'),r={name:"user/use/sites.md"};function i(l,e,c,p,h,n){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="站点与模型" tabindex="-1">站点与模型 <a class="header-anchor" href="#站点与模型" aria-label="Permalink to &quot;站点与模型&quot;">​</a></h1><p>入口：<strong>配置 → 站点管理</strong>。左侧选择站点，右侧编辑该站点的连接信息、默认策略和模型。</p><h2 id="选择接口协议" tabindex="-1">选择接口协议 <a class="header-anchor" href="#选择接口协议" aria-label="Permalink to &quot;选择接口协议&quot;">​</a></h2><p>添加站点时，选择与服务商 API 匹配的接口协议。常规协议会把常用端点预填到可编辑字段中；切换协议时会同步更新端点。自定义 HTTP 没有统一的路径，按服务商文档填写。</p><table tabindex="0"><thead><tr><th>协议</th><th>模型列表端点默认值</th><th>探测端点默认值</th></tr></thead><tbody><tr><td>OpenAI 兼容协议</td><td><code>/models</code></td><td><code>/chat/completions</code></td></tr><tr><td>OpenAI Responses</td><td><code>/models</code></td><td><code>/responses</code></td></tr><tr><td>Anthropic 协议</td><td><code>/models</code></td><td><code>/messages</code></td></tr><tr><td>自定义 HTTP</td><td>留空</td><td>留空</td></tr></tbody></table><p>这些只是界面默认值，不会根据 Base URL 自动添加版本路径。你可以在添加窗口里修改端点；创建后也可以在站点高级设置中调整。模型列表端点留空时跳过远端模型发现，之后可以手动添加模型。</p><h2 id="base-url-与端点怎样填写" tabindex="-1">Base URL 与端点怎样填写 <a class="header-anchor" href="#base-url-与端点怎样填写" aria-label="Permalink to &quot;Base URL 与端点怎样填写&quot;">​</a></h2><p>请求地址严格按输入原文拼接：<strong>Base URL + 端点</strong>。程序不会添加、删除或纠正斜杠，也不会补 <code>/v1</code>、解析相对路径或替换地址。预览、探测、模型获取、IQ 测试和请求记录遵循相同规则。</p><table tabindex="0"><thead><tr><th>Base URL</th><th>端点</th><th>请求地址</th></tr></thead><tbody><tr><td><code>https://api.example.com</code></td><td><code>/models</code></td><td><code>https://api.example.com/models</code></td></tr><tr><td><code>https://api.example.com/v1</code></td><td><code>/responses</code></td><td><code>https://api.example.com/v1/responses</code></td></tr><tr><td><code>https://aitogether.site/usage</code></td><td><code>v1/res</code></td><td><code>https://aitogether.site/usagev1/res</code></td></tr></tbody></table><p>填写时请对照预览确认最终地址。如果服务商要求路径分隔符或版本路径，请在 Base URL 或端点中自行填写。</p><p>模型列表读取失败不会阻止保存站点。检查端点、凭据和服务商要求后，可以在高级设置中修改模型列表端点并同步模型；也可以手动添加模型。</p><h2 id="修改站点信息和-api-key" tabindex="-1">修改站点信息和 API Key <a class="header-anchor" href="#修改站点信息和-api-key" aria-label="Permalink to &quot;修改站点信息和 API Key&quot;">​</a></h2><ol><li>在左侧选中站点。</li><li>修改名称、协议、Base URL 或访问凭据。</li><li>点击“保存变更”。</li></ol><p>已有凭据时，访问凭据输入框留空会保留原值；输入新值并保存会替换凭据。界面显示“已配置凭据”时，不会回显原 API Key。</p><p>基本信息有未保存更改时，模型与探针操作会暂时禁用。先保存变更，再打开高级设置或操作模型。</p><h2 id="同步或手动添加模型" tabindex="-1">同步或手动添加模型 <a class="header-anchor" href="#同步或手动添加模型" aria-label="Permalink to &quot;同步或手动添加模型&quot;">​</a></h2><p><strong>同步模型</strong>用于重新读取服务商目录。模型列表支持服务端游标分页；分页参数只用于后续页面请求，不会改写 Base URL 或端点。出现确认窗口时，检查将新增和移除的模型，再点击“确认同步”。从远端目录消失的模型及其独立设置可能被删除。</p><p><strong>添加模型</strong>用于补充已知的完整模型标识。新增模型默认继承站点探针策略，随后按需开启模型探测。</p><p>模型行中的策略列会显示“继承站点默认”“独立策略”或“自定义策略”，具体配置见<a href="./probes.html">探针配置</a>。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/site-models.webp"><img src="'+t+'" alt="模型列表中的批量探测、同步、添加模型和各行操作入口"></a></p><figcaption>① 站点级模型操作；② 每个模型的启用开关、策略和操作按钮。点击图片可查看大图。</figcaption></figure><h2 id="启停与排序" tabindex="-1">启停与排序 <a class="header-anchor" href="#启停与排序" aria-label="Permalink to &quot;启停与排序&quot;">​</a></h2><ul><li>新建站点默认在小面板中隐藏；站点开关控制小面板显示，并影响自动周期探测。</li><li>模型探测开关控制该模型是否参与常规批量和自动探测。</li><li>单模型“立即探测”是显式手动操作，可以用于验证该模型；批量操作只选择已启用模型。</li><li>拖动左侧站点的排序手柄调整顺序。</li></ul><p>站点顺序会影响优先级和小面板的显示顺序。RelayPulse 是探测工具，不会替其他应用自动切换 API 请求线路。</p><h2 id="删除站点或模型" tabindex="-1">删除站点或模型 <a class="header-anchor" href="#删除站点或模型" aria-label="Permalink to &quot;删除站点或模型&quot;">​</a></h2><p>删除站点会同时删除该站点下的模型和独立设置；删除模型也会失去对应的模型独立配置。操作前先核对确认框里的对象。</p><p>同一站点正在同步、探测或保存时，相关按钮可能暂时不可用，等待当前任务结束后再操作。</p>',26)])])}const _=a(r,[["render",i]]);export{b as __pageData,_ as default};
